def check_condition(p, k):
    x1 = 8 * (p**k)
    # We need to check if x1 divides 2**x1 - 1.
    # This is equivalent to checking if 2**x1 - 1 % x1 == 0.
    # However, since x1 is always even (x1 = 8p^k >= 8), 
    # 2**x1 - 1 is always odd. An even number cannot divide an odd number 
    # unless the odd number is 0, which is impossible here.

    # Let's check the parity just to confirm the analysis.
    target = pow(2, x1) - 1
    print(f"For p={p}, k={k}, x1={x1}:")
    print(f"Is x1 even? {x1 % 2 == 0}")
    print(f"Is target odd? {target % 2 != 0}")

    if x1 > 1 and x1 % 2 == 0 and target % 2 != 0:
        print("Conclusion: No division possible (Even | Odd).")
    elif x1 == 1:
        print("Conclusion: x1=1, division possible trivially.")
    else:
        # Only useful if x1 is odd
        try:
            if target % x1 == 0:
                print("Condition satisfied.")
            else:
                print("Condition not satisfied.")
        except ZeroDivisionError:
            print("x1 is zero, impossible.")

# Test the requested small cases
primes = [2, 3, 5]
ks = [1, 2]

for p in primes:
    for k in ks:
        check_condition(p, k)

